arguments.command:
cat > /tmp/analysis.sql <<'SQL'
WITH base AS (SELECT o.operation_id,CASE WHEN o.opened_at_ms<1777939200000 THEN 'early' ELSE 'late' END period,rg.region_code,cl.class_code,rel.build_code FROM logical_operations o JOIN service_routes sr USING(route_id) JOIN services sv USING(service_id) JOIN route_assignments ra ON ra.route_id=o.route_id AND o.opened_at_ms>=ra.effective_from_ms AND o.opened_at_ms<ra.effective_to_ms JOIN releases rel USING(release_id) JOIN regions rg USING(region_id) JOIN tenants t USING(tenant_id) JOIN operation_classes cl USING(class_id) WHERE sv.service_code='parcel-index' AND ((o.opened_at_ms>=1777852800000 AND o.opened_at_ms<1777856400000) OR (o.opened_at_ms>=1777939200000 AND o.opened_at_ms<1777942800000))), ops AS (SELECT b.*,CASE WHEN f.is_success=0 THEN 1 ELSE 0 END fail FROM base b JOIN attempt_events a ON a.operation_id=b.operation_id AND a.attempt_no=(SELECT max(attempt_no) FROM attempt_events x WHERE x.operation_id=b.operation_id) JOIN failure_codes f USING(code_id)) SELECT period,count(*) n,sum(fail) f,100.0*sum(fail)/count(*) pct,100.0*sum(build_code='idx-r19')/count(*) candidate FROM ops GROUP BY period;
SQL

